!function(e){function n(n){for(var t,a,o=n[0],p=n[1],c=n[2],d=0,u=[];d<o.length;d++)a=o[d],Object.prototype.hasOwnProperty.call(m,a)&&m[a]&&u.push(m[a][0]),m[a]=0;for(t in p)Object.prototype.hasOwnProperty.call(p,t)&&(e[t]=p[t]);for(s&&s(n);u.length;)u.shift()();return i.push.apply(i,c||[]),r()}function r(){for(var e,n=0;n<i.length;n++){for(var r,a=i[n],o=!0,p=1;p<a.length;p++)r=a[p],0!==m[r]&&(o=!1);o&&(i.splice(n--,1),e=t(t.s=a[0]))}return e}function t(n){if(a[n])return a[n].exports;var r=a[n]={i:n,l:!1,exports:{}};return e[n].call(r.exports,r,r.exports,t),r.l=!0,r.exports}var a={},m={42:0},i=[];t.m=e,t.c=a,t.d=function(e,n,r){t.o(e,n)||Object.defineProperty(e,n,{enumerable:!0,get:r})},t.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},t.t=function(e,n){if(1&n&&(e=t(e)),8&n)return e;if(4&n&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(t.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&n&&"string"!=typeof e)for(var a in e)t.d(r,a,function(n){return e[n]}.bind(null,a));return r},t.n=function(e){var n=e&&e.__esModule?function(){return e.default}:function(){return e};return t.d(n,"a",n),n},t.o=function(e,n){return Object.prototype.hasOwnProperty.call(e,n)},t.p="";var o=window.webpackJsonp=window.webpackJsonp||[],p=o.push.bind(o);o.push=n,o=o.slice();for(var c=0;c<o.length;c++)n(o[c]);var s=p;i.push([200,0]),r()}({200:function(e,n,r){"use strict";r.r(n);var t=r(0);Object(t.a)("de","army",r(201),r(1))},201:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"火炮","link":"de_army#de_army_cannon"}],"model":"150mm s.IG33型步兵炮","description":"<p>150mm s.IG33型步兵炮原先是二战中德军陆军配备较多的一种重型火炮，在二战爆发前的1933年已经开始量产，当初由于炮身较重，机动性不理想，在战场转移较困难，因而作为步兵直瞄火力支援用效果并不理想，二战爆发后，由于该炮无穿甲弹，面对战场上对手不断涌现的坦克更显力不从心，直到1942年，德军为150mm s.IG33步兵炮配备了穿甲弹，从而使其具备了反坦克能力，由此成为德军步兵部队具有较强杀伤力同时又能反坦克作战的一种重火力武器；后来德军将部分150mm s.IG33步兵炮直接安装在一些坦克底盘上，使之成为自行重火力炮车，从而发挥出更大威力。</p><p>由于150mm s.IG33步兵炮是一种早期开发的重炮，在射程和射击准确率上相对德军其它重火炮并无优势，但由于其炮弹威力大，有一定野战能力，能直接支持步兵进攻或防御作战，因此在二战期间，德国一直坚持生产该炮，每年都有数百门产出（1941、1942年每年产出400多门）；在东线战场，德国陆军每个团都至少装备20门150mm s.IG33步兵炮。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_cannonIG33_11.jpg","description":"<h6>150mm s.IG33型步兵炮</h6><p></p><p>技术数据：</p><p>火炮口径：150mm（149.1mm）；</p><p>炮管长：1.70米；</p><p>火炮重：战斗1.70吨，运输1.825吨；</p><p>火炮射界（水平方向）：11度，火炮射角（垂直方向）：-4～+75度；</p><p>射速：2～3发/分钟；</p><p>最远射程：4700米。</p>","caption":""}],"part2title":"战场上的150mm s.IG33型步兵炮","part2description":"","part2content":[{"image":"imgs/de/army/de_army_cannonIG33_21.jpg","description":"一门架设在炮阵地中的德军150mm s.IG33步兵炮，该炮的炮弹装药大，尽管炮弹初速只有240米/秒，但爆炸威力极大，是支援德军步兵作战的强大重火力武器。","caption":""},{"image":"imgs/de/army/de_army_cannonIG33_22.jpg","description":"1943年2月，东线苏联战场，武装党卫军炮连使用的一门15mm s.IG33重型步兵炮，炮组成员正在进行训练。注意：该炮的炮管口下方皮带上悬挂的是炮口盖，该炮配置了带辐条的橡胶边车轮和固定在防盾下方的电子制动灯，显然是适应机动运输的需求。","caption":""},{"image":"imgs/de/army/de_army_cannonIG33_23.jpg","description":"1942年1月，东线苏联战场，德国南方集团军某炮兵营下属炮连的一门150mm s.IG33重步兵炮，这门架设在玉米地上的步兵炮正在进行射击，炮兵们都很紧张，显见战斗的激烈。","caption":""},{"image":"imgs/de/army/de_army_cannonIG33_24.jpg","description":"1941年10月，东线苏联战场，在俄罗斯泥泞公路上行进中的德军一门150mm s.IG33重步兵炮；由于路况很差，德军虏来不少苏联村民实施修路，该重炮也只能用马来牵引慢慢行进。","caption":""},{"image":"imgs/de/army/de_army_cannonIG33_25.jpg","description":"东线苏联战场，在火炮阵地中的德军一门150mm s.IG33重步兵炮；该炮安置在土坑中，周边有植物遮掩，因此能使火炮与士兵得到很好的掩护。","caption":""},{"image":"imgs/de/army/de_army_cannonIG33_26.jpg","description":"为了击中掩体后的目标，150mm s.IG33重步兵炮也可以抬高炮口进行曲射，图中150mm步兵炮的炮管已抬高至75度，炮兵可根据打击目标的类型和结构，在有或没有延迟点火的情况下发射炮弹。","caption":""},{"image":"imgs/de/army/de_army_cannonIG33_27.jpg","description":"1942年春季，东线苏联战场，正在作战的德军第14装甲师炮兵连一门150mm s.IG33重步兵炮，为了在雪地中更好地掩护自己，炮兵们都穿上了白色伪装衣。","caption":""},{"image":"imgs/de/army/de_army_cannonIG33_28.jpg","description":"东线苏联战场，雪地中一门正在作战的德军150mm s.IG33重步兵炮。150mm重型步兵炮可以在战场上对付坚固工事，炮弹使用延迟保险丝可以穿透两米厚的地表，当38公斤重的炮弹外壳爆炸时，会产生约1000个碎片，杀伤力十分大。","caption":""},{"image":"imgs/de/army/de_army_cannonIG33_29.jpg","description":"由于150mm s.IG33重步兵炮火力强大，因此德军会将该炮安装在坦克底盘上，改装为具备机动性的自行火炮车。图中为1941年春季在巴尔干地区，德军第9装甲师将150mm步兵炮直接吊装在一辆坦克底盘上，坦克底盘上已加装了火炮的防护装甲板，从而改造为自行炮车。","caption":""},{"image":"imgs/de/army/de_army_cannonIG33_30.jpg","description":"图中是在德军Ⅰ号坦克B型底盘上改装的150mm s.IG33自行重步兵炮车，在1940年夏天，有6辆这样的自行炮车被分配给德国陆军装甲师，这种自行炮车的最后一辆车是在1943年中装备了东线俄罗斯战场上作战的德军第5装甲师。","caption":""}]}')}});